// Deterministic production GGX directional-albedo quadrature. Outputs a reviewable numeric LUT.
#include <cmath>
#include <cstdio>
#include <algorithm>
struct V {double x,y,z;};
V norm(V v){double s=1/std::sqrt(v.x*v.x+v.y*v.y+v.z*v.z);return {v.x*s,v.y*s,v.z*s};}
double radical(unsigned x){x=(x<<16)|(x>>16);x=((x&0x55555555)<<1)|((x&0xaaaaaaaa)>>1);x=((x&0x33333333)<<2)|((x&0xcccccccc)>>2);x=((x&0x0f0f0f0f)<<4)|((x&0xf0f0f0f0)>>4);x=((x&0x00ff00ff)<<8)|((x&0xff00ff00)>>8);return x*0x1p-32;}
int main(){const int A=32,C=32,N=32768;double table[A][C];for(int a=0;a<A;a++){double alpha=std::max(.0005,a/(double)(A-1));for(int c=0;c<C;c++){double z=std::max(.001,c/(double)(C-1)),x=std::sqrt(1-z*z),sum=0;V vh=norm({alpha*x,0,z});V t1={0,1,0},t2={-vh.z,0,vh.x};for(int i=0;i<N;i++){double r=std::sqrt((i+.5)/N),phi=2*M_PI*radical(i),xx=r*std::cos(phi),yy=r*std::sin(phi),s=.5*(1+vh.z);yy=(1-s)*std::sqrt(std::max(0.,1-xx*xx))+s*yy;double zz=std::sqrt(std::max(0.,1-xx*xx-yy*yy));V h=norm({alpha*(t1.x*xx+t2.x*yy+vh.x*zz),alpha*(t1.y*xx+t2.y*yy),std::max(0.,t2.z*yy+vh.z*zz)});double dot=x*h.x+z*h.z,wz=2*dot*h.z-z;if(wz<=0)continue;double lx=.5*(std::sqrt(1+alpha*alpha*(1-z*z)/(z*z))-1),li=.5*(std::sqrt(1+alpha*alpha*(1-wz*wz)/(wz*wz))-1);sum+=(1+lx)/(1+lx+li);}table[a][c]=sum/N;}}
puts("#pragma once\n// Generated by tools/native/generate_ggx_energy.cpp; 32x32, 32768 Hammersley VNDF samples/cell.\nnamespace rt {\n#ifdef __CUDACC__\nstatic __device__ __constant__ const float GgxEnergy[1024]={\n#else\nstatic constexpr float GgxEnergy[1024]={\n#endif");for(auto& row:table){for(double v:row)printf("%.8ff,",v);puts("");}puts("};\nRT_FN float ggxEnergy(float alpha,float cosine){float a=clamp(alpha,0,1)*31,c=clamp(cosine,0,1)*31;int ax=(int)a,cx=(int)c,ay=ax<31?ax+1:ax,cy=cx<31?cx+1:cx;float x=a-ax,y=c-cx;return (GgxEnergy[ax*32+cx]*(1-x)+GgxEnergy[ay*32+cx]*x)*(1-y)+(GgxEnergy[ax*32+cy]*(1-x)+GgxEnergy[ay*32+cy]*x)*y;}\nRT_FN float ggxAverageEnergy(float alpha){float sum=0;for(int i=0;i<16;i++){float c=(i+.5f)/16;sum+=ggxEnergy(alpha,c)*2*c/16;}return sum;}\n}");}
